/**
 * @workspace/config - Centralized Monorepo Configuration & Design Tokens
 */
import tokens from './tailwind/tokens.js';
import preset from './tailwind/preset.js';

export { tokens, preset };
export default { tokens, preset };

/** @type {import('eslint').Linter.Config} */
export default {
  env: {
    browser: true,
    es2022: true,
    node: true,
  },
  parser: '@typescript-eslint/parser',
  parserOptions: {
    ecmaVersion: 'latest',
    sourceType: 'module',
  },
  plugins: ['@typescript-eslint'],
  extends: [
    'eslint:recommended',
    'plugin:@typescript-eslint/recommended',
    'prettier',
  ],
  rules: {
    '@typescript-eslint/no-unused-vars': [
      'warn',
      { argsIgnorePattern: '^_', varsIgnorePattern: '^_' },
    ],
    '@typescript-eslint/consistent-type-imports': [
      'warn',
      { prefer: 'type-imports', fixStyle: 'inline-type-imports' },
    ],
    'no-console': ['warn', { allow: ['warn', 'error'] }],
    'prefer-const': 'error',
    'no-var': 'error',
  },
};

import reactConfig from './react.js';

/** @type {import('eslint').Linter.Config} */
export default {
  ...reactConfig,
  plugins: [...reactConfig.plugins, '@next/next'],
  extends: [
    ...reactConfig.extends,
    'plugin:@next/next/recommended',
    'plugin:@next/next/core-web-vitals',
  ],
  rules: {
    ...reactConfig.rules,
    '@next/next/no-html-link-for-pages': 'off',
  },
};

import baseConfig from './base.js';

/** @type {import('eslint').Linter.Config} */
export default {
  ...baseConfig,
  parserOptions: {
    ...baseConfig.parserOptions,
    ecmaFeatures: {
      jsx: true,
    },
  },
  plugins: [...baseConfig.plugins, 'react', 'react-hooks'],
  extends: [
    ...baseConfig.extends,
    'plugin:react/recommended',
    'plugin:react-hooks/recommended',
    'plugin:react/jsx-runtime',
  ],
  settings: {
    react: {
      version: 'detect',
    },
  },
  rules: {
    ...baseConfig.rules,
    'react/prop-types': 'off',
    'react/react-in-jsx-scope': 'off',
    'react-hooks/rules-of-hooks': 'error',
    'react-hooks/exhaustive-deps': 'warn',
  },
};

