  /** Minimum log level to print to terminal. Defaults to 'INFO'. */
  minLevel?: 'DEBUG' | 'INFO' | 'ACTION' | 'WARN' | 'ERROR';
  /** Print startup terminal banner on Vite server listen. Defaults to true. */
  showBanner?: boolean;
  /** Array of module names to suppress from terminal output. */
  filterModules?: string[];
}

const ANSI = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  gray: '\x1b[90m',
  cyan: '\x1b[36m',
  brightCyan: '\x1b[96m',
  brightGreen: '\x1b[92m',
  brightYellow: '\x1b[93m',
  brightRed: '\x1b[91m',
  brightMagenta: '\x1b[95m',
  brightWhite: '\x1b[97m',

  bgGray: '\x1b[100m\x1b[97m\x1b[1m',
  bgBlue: '\x1b[44m\x1b[97m\x1b[1m',
  bgMagenta: '\x1b[45m\x1b[97m\x1b[1m',
  bgYellow: '\x1b[43m\x1b[30m\x1b[1m',
  bgRed: '\x1b[41m\x1b[97m\x1b[1m',
};

const LEVEL_BADGES: Record<string, string> = {
  DEBUG: `${ANSI.bgGray} DEBUG ${ANSI.reset}`,
  INFO: `${ANSI.bgBlue}  INFO ${ANSI.reset}`,
  ACTION: `${ANSI.bgMagenta} ACTION${ANSI.reset}`,
  WARN: `${ANSI.bgYellow}  WARN ${ANSI.reset}`,
  ERROR: `${ANSI.bgRed} ERROR ${ANSI.reset}`,
};

const MODULE_COLORS: Record<string, string> = {
  API: ANSI.brightCyan,
  ROUTER: ANSI.brightMagenta,
  AUTH: ANSI.brightGreen,
  DATABASE: ANSI.brightGreen,
  WEBSOCKET: ANSI.brightYellow,
  APP: ANSI.cyan,
  PERF: ANSI.brightMagenta,
  WINDOW: ANSI.brightRed,
  PROMISE: ANSI.brightRed,
};

function format5ColumnLine(scope: string, level: string, moduleName: string, message: string): string {
  const now = new Date().toLocaleTimeString('en-US', { hour12: false });
  const colTime = `${ANSI.gray}[${now}]${ANSI.reset}`;
  const colScope = `${ANSI.brightCyan}[${scope.padEnd(8).slice(0, 8)}]${ANSI.reset}`;
  const colBadge = LEVEL_BADGES[level.toUpperCase()] || `[${level.padEnd(7)}]`;

  const tag = (moduleName.toUpperCase() || 'APP').slice(0, 14);
  const tagColor = MODULE_COLORS[tag] || ANSI.cyan;
  const colTag = `${tagColor}${ANSI.bold}[${tag.padEnd(14)}]${ANSI.reset}`;

  let msg = message;
  if (level === 'ERROR') {
    msg = `${ANSI.brightRed}${message}${ANSI.reset}`;
  } else if (level === 'WARN') {
    msg = `${ANSI.brightYellow}${message}${ANSI.reset}`;
  }

  return `${colTime} ${colScope} ${colBadge} ${colTag} ${msg}`;
}

export function workspaceLoggerPlugin(options: ViteLoggerOptions = {}) {
  const channel = options.channel || 'workspace:client-log';
  const scope = (options.scope || 'CLIENT  ').padEnd(8).slice(0, 8);
  const minLevel = options.minLevel || 'INFO';
  const filterModules = new Set(options.filterModules || []);

  const ranks: Record<string, number> = {
    DEBUG: 0,
    INFO: 1,
    ACTION: 2,
    WARN: 3,
    ERROR: 4,
  };

  return {
    name: 'workspace-terminal-logger',

    configureServer(server: any) {
      const handlePayload = (data: any) => {
        if (!data || !data.module) return;

        const level = (data.level || 'INFO').toUpperCase();
        if ((ranks[level] ?? 1) < (ranks[minLevel] ?? 1)) return;

        const mod = String(data.module || 'APP').toUpperCase();
        if (filterModules.has(mod)) return;

        const msg = String(data.message || '').slice(0, 450);
        const line = format5ColumnLine(scope, level, mod, msg);

        console.log(line);
      };

      // 1. Listen on configured Vite HMR channels
      if (server.ws) {
        server.ws.on(channel, handlePayload);
        server.ws.on('client:log', handlePayload);
        if (channel !== 'workspace:client-log') {
          server.ws.on('workspace:client-log', handlePayload);
        }
      }

      // 2. HTTP Fallback endpoint for non-HMR or polling environments
      server.middlewares.use('/__client_log', (req: any, res: any) => {
        if (req.method === 'POST') {
          let body = '';
          req.on('data', (chunk: any) => (body += chunk));
          req.on('end', () => {
            try {
              handlePayload(JSON.parse(body));
            } catch (_) {}
            res.statusCode = 204;
            res.end();
          });
        } else {
          res.statusCode = 405;
          res.end();
        }
      });
    },
  };
}

export const viteTerminalLogger = workspaceLoggerPlugin;
export default workspaceLoggerPlugin;

"""
Cascading Environment Hierarchy & Parser for Workspace Runner (@workspace/runner).
Loads and merges .env files in cascading priority:
  1. Monorepo Root .env (lowest priority defaults)
  2. Monorepo Root .env.local
  3. Project Directory .env
  4. Project Directory .env.local (highest priority overrides)
"""

from __future__ import annotations

import os
import re
from pathlib import Path
from typing import Any

# Sensitive variable key substrings for redaction
_SENSITIVE_PATTERNS = re.compile(
    r"(KEY|SECRET|PASSWORD|TOKEN|AUTH|CREDENTIAL|PRIVATE|CERT)", re.IGNORECASE
)


def parse_env_file(file_path: Path) -> dict[str, str]:
    """
    Parses a single .env file into a dictionary without third-party dependencies.
    Supports comments (#), export prefixes, single/double quotes, and inline comments.
    """
    env_vars: dict[str, str] = {}
    if not file_path.is_file():
        return env_vars

    try:
        content = file_path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return env_vars

    for line in content.splitlines():
        line = line.strip()
        # Skip empty lines or pure comments
        if not line or line.startswith("#"):
            continue

        # Strip optional 'export ' prefix
        if line.startswith("export ") and len(line) > 7:
            line = line[7:].strip()

        # Match KEY=VALUE
        if "=" not in line:
            continue

        key, raw_val = line.split("=", 1)
        key = key.strip()
        if not key:
            continue

        val = raw_val.strip()

        # Handle quoted values
        if len(val) >= 2 and (
            (val.startswith('"') and val.endswith('"'))
            or (val.startswith("'") and val.endswith("'"))
        ):
            val = val[1:-1]
        else:
            # Handle inline comments for unquoted values (e.g. PORT=8000 # default)
            if " #" in val:
                val = val.split(" #", 1)[0].strip()

        env_vars[key] = val

    return env_vars


def _interpolate_variables(env_dict: dict[str, str], base_env: dict[str, str]) -> dict[str, str]:
    """Resolves ${VAR:-default} and ${VAR} style variable expansions."""
    merged = {**base_env, **env_dict}
    resolved: dict[str, str] = {}

    pattern = re.compile(r"\$\{([A-Za-z0-9_]+)(?::-([^}]*))?\}")

    for k, v in env_dict.items():
        def repl(m: re.Match) -> str:
            var_name = m.group(1)
            default_val = m.group(2) or ""
            return merged.get(var_name, default_val)

        resolved[k] = pattern.sub(repl, v)

    return resolved


def load_cascading_env(
    project_dir: Path | None = None,
    repo_root: Path | None = None,
) -> tuple[dict[str, str], list[Path]]:
    """
    Discovers, parses, and cascades .env files across monorepo root and project directory.
    Returns:
        (merged_env_dict, list_of_loaded_env_file_paths)
    """
    if repo_root is None:
        # Default repo root: 3 levels up from this file (packages/runner/workspace_runner/env.py -> workspace)
        repo_root = Path(__file__).resolve().parent.parent.parent.parent

    candidate_files: list[Path] = [
        repo_root / ".env",
        repo_root / ".env.local",
    ]

    if project_dir and project_dir != repo_root:
        candidate_files.extend([
            project_dir / ".env",
            project_dir / ".env.local",
        ])

    loaded_files: list[Path] = []
    accumulated_vars: dict[str, str] = {}

    for f in candidate_files:
        if f.is_file():
            parsed = parse_env_file(f)
            accumulated_vars.update(parsed)
            loaded_files.append(f)

    # Interpolate variables using existing system environment as baseline
    system_env = dict(os.environ)
    final_vars = _interpolate_variables(accumulated_vars, system_env)

    # Synthesize complete environment for subprocess execution
    full_env = {**system_env, **final_vars}

    # Ensure unbuffered output and ANSI terminal colors are forced in child runtimes
    full_env["PYTHONUNBUFFERED"] = "1"
    full_env["FORCE_COLOR"] = "1"

    return full_env, loaded_files


def get_env_summary(project_dir: Path | None = None, repo_root: Path | None = None) -> dict[str, Any]:
    """Generates a secure summary of loaded environment variables with secrets redacted."""
    full_env, loaded_files = load_cascading_env(project_dir, repo_root)

    safe_entries: dict[str, str] = {}
    total_custom_vars = 0

    # Collect custom variables loaded from files
    for f in loaded_files:
        parsed = parse_env_file(f)
        total_custom_vars += len(parsed)
        for k in parsed:
            val = full_env.get(k, "")
            if _SENSITIVE_PATTERNS.search(k) and len(val) > 4:
                safe_entries[k] = f"{val[:2]}••••••••{val[-2:]}"
            elif _SENSITIVE_PATTERNS.search(k):
                safe_entries[k] = "••••••••"
            else:
                safe_entries[k] = val

    return {
        "loaded_files": [str(f) for f in loaded_files],
        "total_variables": total_custom_vars,
        "variables": safe_entries,
    }

